from django.db import migrations, models
from django.utils.text import slugify


def proximo_login_gestor(nome, ocupados):
    # Cópia de funcionarios.models.proximo_login_gestor na data desta migração.
    primeiro_nome = slugify(((nome or '').split() or [''])[0]).replace('-', '') or 'gestor'
    login = primeiro_nome
    sufixo = 2
    while login in ocupados:
        login = f'{primeiro_nome}{sufixo}'
        sufixo += 1
    return login


def preencher_login_dos_gestores(apps, schema_editor):
    # O modelo histórico não tem o save() que gera o login, então os gestores
    # que já existem recebem o deles aqui (por ordem de cadastro: quem chegou
    # primeiro fica com o nome sem número).
    Usuario = apps.get_model('funcionarios', 'Usuario')
    ocupados = set()
    for usuario in Usuario.objects.filter(papel='gestor').select_related('funcionario').order_by('id'):
        usuario.login_gestor = proximo_login_gestor(usuario.funcionario.nome, ocupados)
        ocupados.add(usuario.login_gestor)
        usuario.save(update_fields=['login_gestor'])


